sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float radiusR;
uniform float radiusG;
uniform float radiusB;
uniform float shift;
uniform float shiftAngle;
uniform float amount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 sh = float2(cos(radians(shiftAngle)), sin(radians(shiftAngle))) * shift;
    float3 acc = float3(0.0);
    float aacc = 0.0;
    for (int i = 0; i < 12; i++) {
        float a = float(i) * 2.3999632;
        float r = sqrt((float(i) + 0.5) / 12.0);
        float2 d = float2(cos(a), sin(a)) * r;
        acc.r += tex(coord + sh + d * radiusR).r;
        acc.g += tex(coord + d * radiusG).g;
        acc.b += tex(coord - sh + d * radiusB).b;
        aacc += tex(coord + d * radiusG).a;
    }
    float4 r4 = float4(acc / 12.0, aacc / 12.0);
    return fin(c, mix(c, r4, amount), opacity);
}
